namespace sv_dfdaf6a7616046c2ad475c161846ec65.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public class ThemeService
{
    public ThemeMode CurrentTheme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";
    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        CurrentTheme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        AccentColor = color;
        OnChange?.Invoke();
    }

    public void SetAll(ThemeMode theme, string accentColor)
    {
        CurrentTheme = theme;
        AccentColor = accentColor;
        OnChange?.Invoke();
    }
}

export function applyTheme(theme, accentColor) {
    let resolved = theme;
    if (theme === "system") {
        resolved = window.matchMedia('(prefers-color-scheme: dark)').matches ? "dark" : "light";
    }
    document.documentElement.setAttribute("data-bs-theme", resolved);
    document.documentElement.style.setProperty("--app-accent-color", accentColor);
}

export function getSystemTheme() {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? "dark" : "light";
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

<span class="badge bg-secondary d-inline-flex align-items-center gap-1">
    @switch (ThemeService.CurrentTheme)
    {
        case ThemeMode.Light:
            <span>☀️</span>
            break;
        case ThemeMode.Dark:
            <span>🌙</span>
            break;
        case ThemeMode.System:
            <span>💻</span>
            break;
    }
    <span style="width:12px;height:12px;border-radius:50%;background:@ThemeService.AccentColor;display:inline-block;"></span>
</span>

@code {
    private IJSObjectReference? _module;
    private bool _jsReady;

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>("import", "./js/theme.js");
            _jsReady = true;
            await ApplyTheme();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            StateHasChanged();
            if (_jsReady && _module is not null)
            {
                await ApplyTheme();
            }
        });
    }

    private async Task ApplyTheme()
    {
        if (_module is not null)
        {
            var themeStr = ThemeService.CurrentTheme.ToString().ToLowerInvariant();
            await _module.InvokeVoidAsync("applyTheme", themeStr, ThemeService.AccentColor);
        }
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@inject ThemeService ThemeService
@implements IDisposable

<div class="btn-group" role="group" aria-label="Theme selection">
    <button type="button"
            class="btn @(ThemeService.CurrentTheme == ThemeMode.Light ? "btn-primary" : "btn-outline-primary")"
            @onclick="() => ThemeService.SetTheme(ThemeMode.Light)">
        ☀️ Light
    </button>
    <button type="button"
            class="btn @(ThemeService.CurrentTheme == ThemeMode.Dark ? "btn-primary" : "btn-outline-primary")"
            @onclick="() => ThemeService.SetTheme(ThemeMode.Dark)">
        🌙 Dark
    </button>
    <button type="button"
            class="btn @(ThemeService.CurrentTheme == ThemeMode.System ? "btn-primary" : "btn-outline-primary")"
            @onclick="() => ThemeService.SetTheme(ThemeMode.System)">
        💻 System
    </button>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChange;
    }

    private async void HandleChange()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChange;
    }
}

