@using sv_dfdaf6a7616046c2ad475c161846ec65.Components.Shared

<PageTitle>Settings</PageTitle>

<h1>Settings</h1>

<div class="card mt-4" style="max-width: 500px;">
    <div class="card-header">
        <h5 class="mb-0">User Preferences</h5>
    </div>
    <div class="card-body">
        <div class="mb-3">
            <label class="form-label fw-bold">Theme</label>
            <div>
                <ThemeToggle />
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label fw-bold" for="accentColorInput">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" id="accentColorInput" class="form-control form-control-color"
                       @bind="accentColor" />
                <span class="text-muted">@accentColor</span>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="Save">Save</button>

        <div class="mt-3 text-muted small">
            <strong>Current values:</strong>
            Theme = @ThemeService.CurrentTheme, Accent = @ThemeService.AccentColor
        </div>
    </div>
</div>

@code {
    private string accentColor = "#0d6efd";

    protected override void OnInitialized()
    {
        accentColor = ThemeService.AccentColor;
    }

    private void Save()
    {
        ThemeService.SetAll(ThemeService.CurrentTheme, accentColor);
    }
}

